import{_ as o,c as r,o as t,a2 as s}from"./chunks/framework.QTfwLiL8.js";const u=JSON.parse('{"title":"0011 Apiserver Network Proxy","description":"","frontmatter":{"github_repo":"https://github.com/gardener/enhancements","github_subdir":"geps/0011-apiserver-network-proxy","params":{"github_branch":"main"},"path_base_for_github_subdir":{"from":"content/docs/proposals/0011-apiserver-network-proxy/README.md","to":"README.md"},"title":"0011 Apiserver Network Proxy","prev":false,"next":false},"headers":[],"relativePath":"docs/proposals/0011-apiserver-network-proxy/_index.md","filePath":"docs/proposals/0011-apiserver-network-proxy/_index.md","lastUpdated":null}'),a={name:"docs/proposals/0011-apiserver-network-proxy/_index.md"};function i(n,e,l,h,p,c){return t(),r("div",null,e[0]||(e[0]=[s(`<h1 id="gep-0011-utilize-api-server-network-proxy-to-invert-seed-to-shoot-connectivity" tabindex="-1">GEP-0011: Utilize API Server Network Proxy to Invert Seed-to-Shoot Connectivity <a class="header-anchor" href="#gep-0011-utilize-api-server-network-proxy-to-invert-seed-to-shoot-connectivity" aria-label="Permalink to &quot;GEP-0011: Utilize API Server Network Proxy to Invert Seed-to-Shoot Connectivity&quot;">​</a></h1><ul><li><a href="/docs/proposals/0011-apiserver-network-proxy/readme/#gep-0011-utilize-api-server-network-proxy-to-invert-seed-to-shoot-connectivity">GEP-0011: Utilize API Server Network Proxy to Invert Seed-to-Shoot Connectivity</a><ul><li><a href="/docs/proposals/0011-apiserver-network-proxy/readme/#problem">Problem</a></li><li><a href="/docs/proposals/0011-apiserver-network-proxy/readme/#proposal">Proposal</a><ul><li><a href="/docs/proposals/0011-apiserver-network-proxy/readme/#api-server-network-proxy">API Server Network Proxy</a></li></ul></li><li><a href="/docs/proposals/0011-apiserver-network-proxy/readme/#challenges">Challenges</a><ul><li><a href="/docs/proposals/0011-apiserver-network-proxy/readme/#prometheus-to-shoot-connectivity">Prometheus to Shoot Connectivity</a><ul><li><a href="/docs/proposals/0011-apiserver-network-proxy/readme/#possible-solutions">Possible Solutions</a></li><li><a href="/docs/proposals/0011-apiserver-network-proxy/readme/#port-forwarder-sidecar">Port-Forwarder Sidecar</a></li><li><a href="/docs/proposals/0011-apiserver-network-proxy/readme/#proxy-client-sidecar">Proxy Client Sidecar</a></li><li><a href="/docs/proposals/0011-apiserver-network-proxy/readme/#proxy-sub-resource">Proxy Sub-Resource</a></li></ul></li><li><a href="/docs/proposals/0011-apiserver-network-proxy/readme/#proxy-server-loadbalancer-sharing-and-re-advertising">Proxy-Server Loadbalancer Sharing and Re-Advertising</a><ul><li><a href="/docs/proposals/0011-apiserver-network-proxy/readme/#possible-solution">Possible Solution</a></li></ul></li><li><a href="/docs/proposals/0011-apiserver-network-proxy/readme/#summary">Summary</a></li></ul></li></ul></li></ul><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>Gardener&#39;s architecture for Kubernetes clusters relies on having the control-plane (e.g., kube-apiserver, kube-scheduler, kube-controller-manager) and the data-plane (e.g., kube-proxy, kubelet) of the cluster residing in separate places, this provides many benefits but poses some challenges, especially when API-server to system components communication is required. This problem is solved today in Gardener by <a href="https://github.com/gardener/vpn" target="_blank" rel="noreferrer">making use of OpenVPN</a> to establish a VPN connection from the seed to the shoot. To do so, the following steps are required:</p><ul><li>Create a Loadbalancer service on the shoot.</li><li>Add a sidecar to the API server pod which knows the address of the newly created Loadbalancer.</li><li>Establish a connection over the internet to the VPN Loadbalancer.</li><li>Install additional iptables rules that would redirect all the IPs of the shoot (i.e., service, pod, node CIDRs) to the established VPN tunnel.</li></ul><p>There are, however, quite a few problems with the above approach. Some of them are:</p><ul><li>Every shoot would require an additional loadbalancer, this accounts for additional overhead in terms of both costs and troubleshooting efforts.</li><li>Private access use-cases would not be possible without having a seed residing in the same private domain as a hard requirement. For example, have a look at <a href="https://github.com/gardener/gardener-extension-provider-gcp/issues/56" target="_blank" rel="noreferrer">this issue</a>.</li><li>Providing a public endpoint to access components in the shoot poses a security risk.</li></ul><h2 id="proposal" tabindex="-1">Proposal <a class="header-anchor" href="#proposal" aria-label="Permalink to &quot;Proposal&quot;">​</a></h2><p>There are multiple ways to tackle the directional connectivity issue mentioned above, one way would be to invert the connection between the API server and the system components, i.e., instead of having the API server side-car establish a tunnel, we would have an agent residing in the shoot cluster initiate the connection itself. This way we don&#39;t need a Loadbalancer for every shoot and from the security perspective, there is no ingress from outside, only controlled egress.</p><p>We want to replace this:</p><p><code>APIServer | VPN-seed ---&gt; internet ---&gt; LB --&gt; VPN-Shoot (4314) --&gt; Pods | Nodes | Services</code></p><p>With this:</p><p><code>APIServer &lt;-&gt; Proxy-Server &lt;--- internet &lt;--- Proxy-Agent --&gt; Pods | Nodes | Services</code></p><h3 id="api-server-network-proxy" tabindex="-1">API Server Network Proxy <a class="header-anchor" href="#api-server-network-proxy" aria-label="Permalink to &quot;API Server Network Proxy&quot;">​</a></h3><p>To solve this issue, we can utilize the <a href="https://github.com/kubernetes-sigs/apiserver-network-proxy" target="_blank" rel="noreferrer">apiserver-network-proxy</a> upstream implementation, which provides a reference implementation for a reverse streaming server. The way it works is as follows:</p><ul><li>The proxy agent connects to the proxy server to establish a sticky connection.</li><li>Traffic to the proxy server (residing in the seed) then gets re-directed to the agent (residing in the shoot), which forwards the traffic to in-cluster components.</li></ul><p>The initial motivation for the apiserver-network-proxy project is to get rid of provider-specific implementations that reside in the API-server (e.g., SSH), but it turns out that it has other interesting use-cases such as data-plane connection decoupling, which is the main use-case for this proposal.</p><p>Starting with <strong>Kubernetes 1.18</strong>, it&#39;s possible to make use of an <code>--egress-selector-config-file</code> flag, this helps point the API-server to traffic hook points based on traffic direction. For example, in the config below the API server would have to forward all cluster related traffic (e.g., logs, port-forward, exec) to the <strong>proxy-server</strong>, which then knows how to forward traffic to the shoot. For the rest of the traffic, e.g., API server to ETCD or other control-plane components, <code>direct</code> is used which means legacy routing method, i.e., bypass the proxy.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  egress-selector-configuration.yaml</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|-</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    apiVersion: apiserver.k8s.io/v1alpha1</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    kind: EgressSelectorConfiguration</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    egressSelections:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    - name: cluster</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      connection:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        proxyProtocol: httpConnect</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        transport:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">          tcp:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">            url: https://proxy-server:8131</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    - name: master</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      connection:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        proxyProtocol: direct</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    - name: etcd</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      connection:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        proxyProtocol: direct</span></span></code></pre></div><h2 id="challenges" tabindex="-1">Challenges <a class="header-anchor" href="#challenges" aria-label="Permalink to &quot;Challenges&quot;">​</a></h2><h3 id="prometheus-to-shoot-connectivity" tabindex="-1">Prometheus to Shoot Connectivity <a class="header-anchor" href="#prometheus-to-shoot-connectivity" aria-label="Permalink to &quot;Prometheus to Shoot Connectivity&quot;">​</a></h3><p>One challenge remains to completely eliminate the need for a VPN connection. In today&#39;s Gardener setup, each control-plane has a Prometheus instance that directly scrapes cluster components such as CoreDNS, Kubelets, cadvisor, etc. This works because in addition to the VPN side car attached to the API server pod, we have another one attached to prometheus which knows how to forward traffic to these endpoints. Once the VPN is eliminated, it is required to find other means to forward traffic to these components.</p><h4 id="possible-solutions" tabindex="-1">Possible Solutions <a class="header-anchor" href="#possible-solutions" aria-label="Permalink to &quot;Possible Solutions&quot;">​</a></h4><p>There are currently two ways to solve this problem:</p><ul><li>Attach a port-forwarder side-car to prometheus.</li><li>Utilize the proxy subresource on the API server.</li></ul><h4 id="port-forwarder-sidecar" tabindex="-1">Port-Forwarder Sidecar <a class="header-anchor" href="#port-forwarder-sidecar" aria-label="Permalink to &quot;Port-Forwarder Sidecar&quot;">​</a></h4><p>With this solution, each prometheus instance would have a side-car that has the kubeconfig of the shoot cluster, and which establishes a port-forward connection to the endpoints residing in the shoot.</p><p>There are a many problems with this approach:</p><ul><li>The port-forward connection is not reliable.</li><li>The connection would break if the API server instance dies.</li><li>Requires an additional component.</li><li>Would need to expose every pod / service via port-forward.</li></ul><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Prom Pod (Prometheus -&gt; Port-forwarder) &lt;-&gt; APIServer -&gt; Proxy-server &lt;--- internet &lt;--- Proxy-Agent --&gt; Pods | Nodes | Services</span></span></code></pre></div><h4 id="proxy-client-sidecar" tabindex="-1">Proxy Client Sidecar <a class="header-anchor" href="#proxy-client-sidecar" aria-label="Permalink to &quot;Proxy Client Sidecar&quot;">​</a></h4><p>Another solution would be to implement a proxy-client as a sidecar for every component that wishes to communicate with the shoot cluster. For this to work, means to re-direct / inject that proxy to handle the component&#39;s traffic is necessary (e.g., additional IPtable rules).</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Prometheus Pod (Prometheus -&gt; Proxy) &lt;-&gt; Proxy-Server &lt;--- internet &lt;--- Proxy-Agent --&gt; Pods | Nodes | Services</span></span></code></pre></div><p>The problem with this approach is that it requires an additional sidecar (along with traffic redirection) to be attached to every client that wishes to communicate with the shoot cluster, this can cause:</p><ul><li>Additional maintenance efforts (extra code).</li><li>Other side-effects (e.g., if istio sidecar injection is enabled).</li></ul><h4 id="proxy-sub-resource" tabindex="-1">Proxy Sub-Resource <a class="header-anchor" href="#proxy-sub-resource" aria-label="Permalink to &quot;Proxy Sub-Resource&quot;">​</a></h4><p>Kubernetes supports proxying requests to nodes, services, and pod endpoints in the shoot cluster. This proxy connection can be utilized for scraping the necessary endpoints in the shoot.</p><p>This approach requires less components and is more reliable than the port-forward solution, however, it relies on having the API server supporting proxied connection for the required endpoints.</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Prometheus  &lt;-&gt; APIServer &lt;-&gt; Proxy-Server &lt;--- internet &lt;--- Proxy-Agent --&gt; Pods | Nodes | Services</span></span></code></pre></div><p>As simple as it is, it has a downside that it relies on the availability of the API server.</p><h3 id="proxy-server-loadbalancer-sharing-and-re-advertising" tabindex="-1">Proxy-Server Loadbalancer Sharing and Re-Advertising <a class="header-anchor" href="#proxy-server-loadbalancer-sharing-and-re-advertising" aria-label="Permalink to &quot;Proxy-Server Loadbalancer Sharing and Re-Advertising&quot;">​</a></h3><p>With the proxy-server in place, we need to provide means to enable the proxy-agent in the shoot to establish the connection with the server. As a result, we need to provide a public endpoint through which this channel of communication can be established, i.e., we need a Loadbalancer(s).</p><h4 id="possible-solution" tabindex="-1">Possible Solution <a class="header-anchor" href="#possible-solution" aria-label="Permalink to &quot;Possible Solution&quot;">​</a></h4><p>Using a Loadbalancer / proxy server would not make sense, since this is a pain-point we are trying to eliminate in the first-place, doing so just moves the costs to the control-plane. A possible solution is to communicate over a shared loadbalancer in the seed, similar to what has been proposed in the <a href="https://github.com/gardener/enhancements/blob/main/geps/0011-apiserver-network-proxy/08-shoot-apiserver-via-sni.md" target="_blank" rel="noreferrer">SNI Passthrough Proxy for kube-apiservers</a> proposal, this way we can prevent the extra-costs for load-balancers.</p><p>With this in mind, we still have other pain-points, namely:</p><ul><li>Advertising Loadbalancer public IPs to the shoot.</li><li>Directing the traffic to the corresponding shoot proxy-server.</li></ul><p>For advertising the Loadbalancer IP, a DNS entry can be created for the proxy loadbalancer (or re-use the DNS entry for the SNI proxy), along with necessary certificates, which is then used to connect to the loadbalancer. At this point we can decide on either one of the two approaches:</p><ol><li>One Proxy / API server with a shared loadbalancer.</li><li>Use one proxy server for all agents.</li></ol><p>In the first case, we will probably need a proxy for the proxy-server that knows how to direct traffic to the correct proxy server based on the corresponding shoot cluster. In the second case, we don&#39;t need another proxy if the proxy server is cluster-aware, i.e., can pool and identify connections coming from the same cluster and peer them with the correct API. Unfortunately, the second case is not supported today.</p><h3 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><ul><li>API server proxy can be utilized to invert the connection (only for clusters &gt;= 1.18, for older clusters the old VPN solution will remain).</li><li>This is achieved by utilizing the <code>--egress-selector-config-file</code> flag on the api-server.</li><li>For monitoring endpoints, the proxy subresources would be the preferable methods to go, but in the future we can also support sidecar proxies that can communicate with the proxy-server.</li><li>For directing traffic to the correct proxy-server, we will re-use the SNI proxy along with the load-balancer from <a href="https://github.com/gardener/enhancements/blob/main/geps/0011-apiserver-network-proxy/08-shoot-apiserver-via-sni.md" target="_blank" rel="noreferrer">the shoot API server via SNI GEP</a>.</li></ul>`,51)]))}const v=o(a,[["render",i]]);export{u as __pageData,v as default};
